package com.foodydelivery.tracker.config;
import java.util.List;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import com.foodydelivery.tracker.auth.JwtService; import com.foodydelivery.tracker.user.UserRepository; import jakarta.servlet.http.*; import java.io.IOException; import org.springframework.context.annotation.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.filter.OncePerRequestFilter;
@Configuration public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain chain(HttpSecurity h,JwtFilter f)throws Exception{return h.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/error").permitAll().anyRequest().authenticated()).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class).build();} @Bean JwtFilter jwtFilter(JwtService j,UserRepository u){return new JwtFilter(j,u);} public static class JwtFilter extends OncePerRequestFilter {private final JwtService jwt;private final UserRepository users; public JwtFilter(JwtService j,UserRepository u){jwt=j;users=u;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{String e=jwt.email(h.substring(7));users.findByEmailIgnoreCase(e).ifPresent(u->SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(e,null,List.of())));}catch(RuntimeException ignored){}c.doFilter(r,s);} } }
